116	__aicore__ inline void Compute()
117	{
118	    AscendC::LocalTensor<half> xLocal = inQueueX.DeQue<half>();
119	    AscendC::LocalTensor<half> yLocal = inQueueY.DeQue<half>();
120	    AscendC::LocalTensor<half> zLocal = outQueueZ.AllocTensor<half>();
121	    AscendC::Add(zLocal, xLocal, yLocal, TOTAL_LENGTH);
122	    outQueueZ.EnQue<half>(zLocal);
123	    inQueueX.FreeTensor(xLocal);
124	    inQueueY.FreeTensor(yLocal);
125	}
126	```
