129	
130	```cpp
131	__aicore__ inline void CopyOut()
132	{
133	    AscendC::LocalTensor<half> zLocal = outQueueZ.DeQue<half>();
134	    AscendC::DataCopy(zGm, zLocal, TOTAL_LENGTH);
135	    outQueueZ.FreeTensor(zLocal);
136	}
137	```
