151	AscendC::LocalTensor<float> tmp0 = tmpBuf0.Get<float>();
152	AscendC::Cast(tmp0, xLocal, AscendC::RoundMode::CAST_NONE, TOTAL_LENGTH);
153	AscendC::Add(tmp2, tmp0, tmp1, TOTAL_LENGTH);
154	AscendC::Cast(zLocal, tmp2, AscendC::RoundMode::CAST_RINT, TOTAL_LENGTH);
