    const gert::StorageShape* x_shape = context->GetInputShape(0);
    uint32_t totalSize = x_shape->GetOriginShape().GetShapeSize();
    const gert::Shape shape = x_shape->GetStorageShape();
    uint32_t N = shape.GetDim(0);
