    const float* epsilonAttr = context->GetAttrs()->GetAttrPointer<float>(1);

    uint32_t numGroups = static_cast<uint32_t>(*numGroupsAttr);
    float epsilon = *epsilonAttr;
    uint32_t channelsPerGroup = C / numGroups;
    uint32_t groupSize = channelsPerGroup * spatialSize;
    uint32_t totalRows = N * numGroups;

    uint32_t blockDim = (totalRows < 32) ? totalRows : 32;
    uint32_t rowsPerCore = totalRows / blockDim;
    uint32_t extraRows = totalRows % blockDim;

    tiling.set_numGroups(numGroups);
    tiling.set_channelsPerGroup(channelsPerGroup);
    tiling.set_spatialSize(spatialSize);
    tiling.set_groupSize(groupSize);
    tiling.set_totalRows(totalRows);
